<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import { api, apiMessage } from '@/api/client';
import type { PageResponse, Plan, Tag, Task, TimeEntry, TrashItem } from '@/types';
import { downloadFile } from '@/download';

function shift(days: number) { const date = new Date(); date.setDate(date.getDate() + days); return date.toLocaleDateString('sv-SE'); }
function duration(seconds: number) { const h = Math.floor(seconds / 3600); const m = Math.floor(seconds % 3600 / 60); const s = seconds % 60; return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`; }
const from = ref(shift(-29)); const to = ref(shift(0)); const page = ref(0); const size = ref(20); const ledger = ref<PageResponse<TimeEntry> | null>(null); const trash = ref<TrashItem[]>([]); const plans = ref<Plan[]>([]); const tags = ref<Tag[]>([]); const tasks = ref<Task[]>([]); const planId = ref(''); const tagId = ref(''); const taskId = ref(''); const source = ref(''); const error = ref(''); const busy = ref(false);
function filterParams() { return { from: from.value, to: to.value, page: page.value, size: size.value, planId: planId.value || undefined, tagId: tagId.value || undefined, taskId: taskId.value || undefined, source: source.value || undefined }; }
async function loadLedger() { try { ledger.value = (await api.get<PageResponse<TimeEntry>>('/time-entries', { params: filterParams() })).data; } catch (exception) { error.value = apiMessage(exception); } }
async function loadTrash() { try { trash.value = (await api.get<TrashItem[]>('/trash')).data; } catch (exception) { error.value = apiMessage(exception); } }
async function loadPlans() { try { plans.value = (await api.get<Plan[]>('/plans')).data; } catch (exception) { error.value = apiMessage(exception); } }
async function loadPlanOptions() {
  tagId.value = ''; taskId.value = ''; tags.value = []; tasks.value = [];
  if (!planId.value) return;
  try { const [tagResponse, taskResponse] = await Promise.all([api.get<Tag[]>(`/plans/${planId.value}/tags`), api.get<Task[]>(`/plans/${planId.value}/tasks`)]); tags.value = tagResponse.data; tasks.value = taskResponse.data; }
  catch (exception) { error.value = apiMessage(exception); }
}
async function download() { try { const { page: ignoredPage, size: ignoredSize, ...params } = filterParams(); const response = await api.get('/time-entries/export', { params, responseType: 'blob' }); await downloadFile(response.data as Blob, `plan-time-ledger-${from.value}-${to.value}.csv`); } catch (exception) { error.value = apiMessage(exception); } }
async function restore(item: TrashItem) { busy.value = true; try { await api.post(`/trash/${item.type}/${item.id}/restore`); await Promise.all([loadTrash(), loadLedger(), loadPlans()]); } catch (exception) { error.value = apiMessage(exception); } finally { busy.value = false; } }
async function purge(item: TrashItem) { if (!confirm(`永久删除“${item.title}”？此操作无法恢复。`)) return; busy.value = true; try { await api.delete(`/trash/${item.type}/${item.id}`); await loadTrash(); } catch (exception) { error.value = apiMessage(exception); } finally { busy.value = false; } }
function typeLabel(type: TrashItem['type']) { return type === 'TASK' ? '任务' : type === 'MILESTONE' ? '里程碑' : type === 'TEMPLATE' ? '模板' : type === 'PLAN' ? '计划' : type === 'TAG' ? '标签' : type === 'MAINLINE' ? '主线' : '主线步骤'; }
watch(planId, async () => { await loadPlanOptions(); page.value = 0; await loadLedger(); }); watch([from, to, page, size, tagId, taskId, source], loadLedger); onMounted(() => Promise.all([loadLedger(), loadTrash(), loadPlans()]));
</script>

<template>
  <div class="page records-page"><header class="page-head"><div><p class="eyebrow">RECORDS / TIME / RECOVERY</p><h1>记录与恢复</h1><p>计时流水可按业务来源筛选；删除内容先进入回收站，确认后才会永久清理。</p></div></header><p v-if="error" class="error-text">{{ error }}</p>
    <section class="records-section"><header class="section-title"><div><p class="eyebrow">TIME LEDGER / PAGINATED</p><h2>计时流水</h2></div><button class="btn" @click="download">导出 CSV</button></header><div class="records-filter records-filter--wide"><label>开始<input v-model="from" type="date" :max="to" /></label><label>结束<input v-model="to" type="date" :min="from" /></label><label>计划<select v-model="planId"><option value="">全部计划</option><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{ plan.name }}</option></select></label><label>标签<select v-model="tagId" :disabled="!planId"><option value="">全部标签</option><option v-for="tag in tags" :key="tag.id" :value="tag.id">{{ tag.name }}</option></select></label><label>任务<select v-model="taskId" :disabled="!planId"><option value="">全部任务</option><option v-for="task in tasks" :key="task.id" :value="task.id">{{ task.date }} · {{ task.title }}</option></select></label><label>来源<select v-model="source"><option value="">全部来源</option><option value="TIMER">计时器</option><option value="MANUAL">手动补录</option><option value="LEGACY">旧版迁移</option></select></label><label>每页<select v-model.number="size"><option :value="20">20 项</option><option :value="50">50 项</option><option :value="100">100 项</option></select></label></div><div class="table-scroll"><table><thead><tr><th>开始时间</th><th>任务</th><th>标签</th><th>来源</th><th>实际时长</th></tr></thead><tbody><tr v-for="entry in ledger?.content" :key="entry.id"><td>{{ new Date(entry.startedAt).toLocaleString('zh-CN') }}</td><td>{{ entry.taskTitle }}</td><td><i class="tag-dot" :style="{ background: entry.tagColor ?? '#667085' }" />{{ entry.tagName }}</td><td>{{ entry.source }}</td><td>{{ duration(entry.seconds) }}</td></tr></tbody></table></div><p v-if="!ledger?.content.length" class="empty">所选范围没有计时记录。</p><footer class="pagination-bar"><span>第 {{ (ledger?.page ?? 0) + 1 }} / {{ Math.max(ledger?.totalPages ?? 0, 1) }} 页</span><div class="button-row"><button class="btn" :disabled="!ledger || ledger.page === 0" @click="page--">上一页</button><button class="btn" :disabled="!ledger || ledger.page >= ledger.totalPages - 1" @click="page++">下一页</button></div></footer></section>
    <section class="records-section"><header class="section-title"><div><p class="eyebrow">RECYCLE BIN</p><h2>回收站</h2></div><span>{{ trash.length }}</span></header><article v-for="item in trash" :key="`${item.type}-${item.id}`" class="trash-row"><div><span class="tag">{{ typeLabel(item.type) }}</span><h3>{{ item.title }}</h3><p>{{ item.detail }} · 删除于 {{ new Date(item.deletedAt).toLocaleString('zh-CN') }}</p></div><div class="button-row"><button class="btn primary" :disabled="busy" @click="restore(item)">恢复</button><button class="btn danger" :disabled="busy" @click="purge(item)">永久删除</button></div></article><p v-if="!trash.length" class="empty">回收站为空。</p></section>
  </div>
</template>
